class Solution {
public:
    long long maximumScoreAfterOperations(vector<vector<int>>& edges, vector<int>& values) {
        int n = values.size();
        vector<vector<int>> adj(n);
        for (auto& e : edges) {
            adj[e[0]].push_back(e[1]);
            adj[e[1]].push_back(e[0]);
        }
        long long total = 0;
        for (int v : values) total += v;
        function<long long(int, int)> dfs = [&](int u, int p) -> long long {
            bool is_leaf = true;
            long long child_loss = 0;
            for (int v : adj[u]) {
                if (v != p) {
                    is_leaf = false;
                    child_loss += dfs(v, u);
                }
            }
            if (is_leaf) return values[u];
            return min((long long) values[u], child_loss);
        };
        return total - dfs(0, -1);
    }
};

class Solution {
    List<Integer>[] adj;
    int[] values;
    long dfs(int u, int p) {
        boolean isLeaf = true;
        long childLoss = 0;
        for (int v : adj[u]) {
            if (v != p) {
                isLeaf = false;
                childLoss += dfs(v, u);
            }
        }
        if (isLeaf) return values[u];
        return Math.min(values[u], childLoss);
    }
    public long maximumScoreAfterOperations(int[][] edges, int[] values) {
        int n = values.length;
        this.values = values;
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        long total = 0;
        for (int v : values) total += v;
        return total - dfs(0, -1);
    }
}

