var maximumScoreAfterOperations = function(edges, values) {
    const n = values.length;
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
        adj[v].push(u);
    }
    let total = 0n;
    for (const v of values) total += BigInt(v);
    function dfs(u, p) {
        let isLeaf = true;
        let childLoss = 0n;
        for (const v of adj[u]) {
            if (v !== p) {
                isLeaf = false;
                childLoss += dfs(v, u);
            }
        }
        if (isLeaf) return BigInt(values[u]);
        const valU = BigInt(values[u]);
        return valU < childLoss ? valU : childLoss;
    }
    return Number(total - dfs(0, -1));
};
